import React, { useState, useEffect, useRef } from 'react';
import { Flow, MediaItem, ImageGenerateResult } from 'flow-sdk';
import { SectionLabel, PillButton, TextInput, FieldDropdown, PromptModal, SegmentedToggle, DragNumberField, IconToggleBar } from './components/Primitives';
import { MultiImageUpload } from './components/MultiImageUpload';

// --- Types ---
interface ValidationData {
  productFidelity: number;
  wearingRealism: number;
  pass: boolean;
  reason: string;
  isRetry: boolean;
}

interface ShotResult extends ImageGenerateResult {
  validation?: ValidationData;
}

interface CampaignPreset {
  name: string;
  productLock: string;
  identityLock: string;
  garmentLock: string;
  seed: number;
  isSeedLocked: boolean;
  model: string;
  aspectRatio: string;
  adaptiveFraming: boolean;
  autoValidate: boolean;
}

// --- Optimized Directives (Keyword-Dense & Condensed) ---
const PHOTO_REALISM_DIRECTIVE = "PHOTO-REALISM: Pro mirrorless capture. Pores, fine hair, subsurface scattering. Sharp fabric weave, metal/gemstone reflections.";
const STYLE_CONSISTENCY_DIRECTIVE = "STYLE: Luxury jewelry editorial. Ultra-detailed 8k photorealism.";
const PRODUCT_ACCURACY_DIRECTIVE = "FIDELITY: SKU references are absolute source of truth for jewelry geometry and materials.";
const LIGHTING_ENV_DIRECTIVE = "LIGHTING: Studio softbox. Crisp specular highlights. Natural ambient occlusion.";
const COMPOSITION_RULES = "COMPOSITION: High-fashion framing. Product-focused depth of field.";
const WEARING_REALISM_DIRECTIVE = "PHYSICS: Jewelry obeys gravity (drapes naturally). Accurate contact shadows where metal meets skin.";
const GARMENT_STABILITY_DIRECTIVE = "OUTFIT-STABILITY: The garment is physically locked. Neckline shape, collar, and sleeves are immutable across all angles.";
const NEGATIVE_CONSTRAINTS = "NEGATIVES: Floating parts, waxy skin, painterly style, anatomy errors, wrong stone counts, changing clothes.";

// --- Default Campaign Compositions ---
const CAMPAIGN_SHOTS = [
  { id: 'HERO FRONTAL', type: 'medium', framing: "Head-and-shoulders. Frontal.", angle: "85mm f/1.4. Head-on.", pose: "Direct gaze." },
  { id: '3/4 POSE', type: 'medium', framing: "Chest-up. 45-degree.", angle: "85mm lens.", pose: "S-curve posture." },
  { id: 'STRICT PROFILE', type: 'close-up', framing: "Head-and-shoulders profile.", angle: "85mm side view.", pose: "Jawline elongated." },
  { id: 'MACRO DETAIL', type: 'close-up', framing: "Extreme macro close-up.", angle: "100mm Macro. Shallow DoF.", pose: "Jewelry fills frame." },
  { id: 'OVER-SHOULDER', type: 'wide', framing: "Waist-up. Elevated.", angle: "50mm high angle.", pose: "Over-the-shoulder." },
  { id: 'FULL-LENGTH', type: 'wide', framing: "Full-length standing.", angle: "35mm wide lens.", pose: "High-fashion stance." },
  { id: '3/4 EDITORIAL', type: 'wide', framing: "Mid-thigh up.", angle: "50mm lens.", pose: "Sophisticated editorial." }
];

export default function App() {
  const [productRefs, setProductRefs] = useState<MediaItem[]>([]);
  const [styleRefs, setStyleRefs] = useState<MediaItem[]>([]);
  const [batchCustomDirective, setBatchCustomDirective] = useState('');
  const [model, setModel] = useState('🍌 Nano Banana Pro');
  const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '9:16' | '4:3' | '3:4'>('3:4');
  const [activeTab, setActiveTab] = useState<'Single' | 'Campaign'>('Campaign');
  const [adaptiveFraming, setAdaptiveFraming] = useState(true);
  const [autoValidate, setAutoValidate] = useState(true);
  const [seed, setSeed] = useState(42);
  const [isSeedLocked, setIsSeedLocked] = useState(true);

  const [results, setResults] = useState<ShotResult[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [appStatus, setAppStatus] = useState<'idle' | 'analyzing' | 'reviewing' | 'generating'>('idle');

  const [productLock, setProductLock] = useState('');
  const [identityLock, setIdentityLock] = useState('');
  const [garmentLock, setGarmentLock] = useState('');

  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });
  const [error, setError] = useState<string | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [refiningTarget, setRefiningTarget] = useState<ShotResult | null>(null);
  const [presets, setPresets] = useState<CampaignPreset[]>([]);

  const stopRequested = useRef(false);

  // --- Utility: Safety Truncation ---
  const safePrompt = (txt: string, limit = 3800) => txt.length > limit ? txt.slice(0, limit) : txt;

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (!document.getElementById(id)) {
      const style = document.createElement('style');
      style.id = id;
      style.textContent = `
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 4px; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', sans-serif; letter-spacing: 0.1px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .fade-in { animation: fadeIn 0.4s ease-out forwards; }
        @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
        .animate-shimmer { background: linear-gradient(90deg, #111 25%, #222 50%, #111 75%); background-size: 200% 100%; animation: shimmer 2s infinite; }
        @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
        .pulse-ring { animation: pulse-ring 2s infinite ease-in-out; }
        @keyframes pulse-ring { 0% { transform: scale(0.95); opacity: 0.5; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.5; } }
      `;
      document.head.appendChild(style);
    }
    try {
      const saved = localStorage.getItem('jewelry_campaign_presets');
      if (saved) setPresets(JSON.parse(saved));
    } catch (e) {}
  }, []);

  const saveToPresets = () => {
    const name = prompt("Enter preset name:");
    if (!name) return;
    const newPreset: CampaignPreset = {
      name, productLock, identityLock, garmentLock, seed, isSeedLocked, model, aspectRatio, adaptiveFraming, autoValidate
    };
    const updated = [...presets, newPreset];
    setPresets(updated);
    localStorage.setItem('jewelry_campaign_presets', JSON.stringify(updated));
  };

  const loadPreset = (p: CampaignPreset) => {
    setProductLock(p.productLock);
    setIdentityLock(p.identityLock);
    setGarmentLock(p.garmentLock || '');
    setSeed(p.seed);
    setIsSeedLocked(p.isSeedLocked);
    setModel(p.model);
    setAspectRatio(p.aspectRatio as any);
    setAdaptiveFraming(p.adaptiveFraming);
    setAutoValidate(p.autoValidate);
  };

  const analyzeAndLock = async () => {
    setIsAnalyzing(true);
    setAppStatus('analyzing');
    try {
      const productPrompt = `Analyze SKU. Return CONCISE productLock: metal, stones, setting. NO PREAMBLE. MAX 500 CHARS.`;
      const identityPrompt = `Analyze Mood and "${batchCustomDirective}". Return identityLock: model features, hair, skin, environment. NO CLOTHING. MAX 500 CHARS.`;
      const garmentPrompt = `Analyze Mood and "${batchCustomDirective}". Output ONE precise, fixed outfit specification: exact neckline (neckline shape, depth, collar), sleeves (type, length), silhouette/drape, fabric, and color. NO PREAMBLE. MAX 300 CHARS.`;

      const prodRefs = productRefs.map(m => ({ base64: m.base64, mimeType: m.mimeType }));
      const stylRefs = styleRefs.map(m => ({ base64: m.base64, mimeType: m.mimeType }));

      const [{ text: prodText }, { text: idenText }, { text: garmText }] = await Promise.all([
        Flow.generate.text(safePrompt(productPrompt), { images: prodRefs, systemInstruction: "Forensic jewelry analyst." }),
        Flow.generate.text(safePrompt(identityPrompt), { images: stylRefs, systemInstruction: "High-fashion editorial director." }),
        Flow.generate.text(safePrompt(garmentPrompt), { images: stylRefs, systemInstruction: "Fashion technical designer." })
      ]);

      setProductLock(prodText.trim().slice(0, 500));
      setIdentityLock(idenText.trim().slice(0, 500));
      setGarmentLock(garmText.trim().slice(0, 300));
      setAppStatus('reviewing');
    } catch (err: any) {
      setError("Analysis failed. Using manual baseline.");
      setAppStatus('reviewing');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const generateAdaptiveShots = async (pLock: string, iLock: string) => {
    try {
      const prompt = `Based on: ${pLock} and ${iLock}, generate exactly 7 shots. JSON: [{ "id", "type", "framing", "angle", "pose" }]`;
      const { text } = await Flow.generate.text(safePrompt(prompt), { systemInstruction: "Campaign planner." });
      return JSON.parse(text.replace(/```json|```/g, '').trim()).slice(0, 7);
    } catch (err) {
      return CAMPAIGN_SHOTS;
    }
  };

  const performQC = async (generatedBase64: string, mimeType: string, pLock: string): Promise<ValidationData> => {
    const prompt = `QC generated image against: ${pLock}. JSON: { "productFidelity": 0-100, "wearingRealism": 0-100, "pass": bool, "reason": str }`;
    const imagesToVerify = [{ base64: generatedBase64, mimeType }, ...productRefs.slice(0, 2).map(m => ({ base64: m.base64, mimeType: m.mimeType }))];
    try {
      const { text } = await Flow.generate.text(safePrompt(prompt), { images: imagesToVerify, systemInstruction: "Jewelry QC inspector." });
      const data = JSON.parse(text.replace(/```json|```/g, '').trim());
      return { ...data, isRetry: false };
    } catch (e) {
      return { productFidelity: 100, wearingRealism: 100, pass: true, reason: "QC Bypass.", isRetry: false };
    }
  };

  const runGeneration = async (shotConfig: any, pLock: string, iLock: string, gLock: string, shotSeed: number, correctionInstruction?: string) => {
    const limit = model === 'Imagen 4' ? 3 : 10;
    const rawPrompt = `
      FRAMING: ${shotConfig.framing}.
      PRODUCT_LOCKED: ${pLock}
      IDENTITY_LOCKED: ${iLock}
      GARMENT_LOCKED: ${gLock}
      DEFENSIVE: Camera framing and pose must NEVER change the garment's neckline, cut, sleeves or silhouette. The outfit is identical in all shots regardless of angle or crop.
      ${correctionInstruction ? `CORRECTION: ${correctionInstruction}` : ''}
      ${PHOTO_REALISM_DIRECTIVE} | ${STYLE_CONSISTENCY_DIRECTIVE} | ${PRODUCT_ACCURACY_DIRECTIVE}
      ${LIGHTING_ENV_DIRECTIVE} | ${COMPOSITION_RULES} | ${WEARING_REALISM_DIRECTIVE} | ${GARMENT_STABILITY_DIRECTIVE}
      SHOT: ${shotConfig.id} | ANGLE: ${shotConfig.angle} | POSE: ${shotConfig.pose}
      SEED: ${shotSeed} | ${NEGATIVE_CONSTRAINTS}
    `.trim();

    return await Flow.generate.image({
      prompt: safePrompt(rawPrompt, 3800),
      modelDisplayName: model,
      aspectRatio,
      referenceImageMediaIds: [...productRefs, ...styleRefs].map(m => m.mediaId).slice(0, limit)
    });
  };

  const handleLaunchCampaign = async () => {
    if (productRefs.length === 0) return setError("Product images required.");
    setError(null);
    await analyzeAndLock();
  };

  const confirmAndLaunch = async () => {
    setIsGenerating(true);
    setAppStatus('generating');
    stopRequested.current = false;

    try {
      const activeShots = activeTab === 'Campaign' ? (adaptiveFraming ? await generateAdaptiveShots(productLock, identityLock) : CAMPAIGN_SHOTS) : [CAMPAIGN_SHOTS[0]];
      const total = activeShots.length;
      setBatchProgress({ current: 0, total });

      for (let i = 0; i < total; i++) {
        if (stopRequested.current) break;
        const currentSeed = isSeedLocked ? seed : Math.floor(Math.random() * 999999);

        let result = await runGeneration(activeShots[i], productLock, identityLock, garmentLock, currentSeed);
        let validation: ValidationData | undefined;

        if (autoValidate) {
          validation = await performQC(result.base64, result.mimeType, productLock);
          if (!validation.pass) {
            const retrySeed = isSeedLocked ? seed : Math.floor(Math.random() * 999999);
            const retryResult = await runGeneration(activeShots[i], productLock, identityLock, garmentLock, retrySeed, validation.reason);
            result = retryResult;
            validation = { ...(await performQC(retryResult.base64, retryResult.mimeType, productLock)), isRetry: true };
          }
        }

        setResults(prev => [{ ...result, validation }, ...prev]);
        setBatchProgress(prev => ({ ...prev, current: i + 1 }));
      }
    } catch (err: any) {
      setError("Execution interrupted.");
    } finally {
      setIsGenerating(false);
      setAppStatus('idle');
    }
  };

  const handleRefine = async (refinePrompt: string) => {
    if (!refiningTarget) return;
    setIsEditModalOpen(false);
    setIsGenerating(true);
    try {
      const rSeed = isSeedLocked ? seed : Math.floor(Math.random() * 999999);
      const promptText = `REFINE: ${refinePrompt}. PRODUCT_LOCKED: ${productLock}. IDENTITY_LOCKED: ${identityLock}. GARMENT_LOCKED: ${garmentLock}. SEED: ${rSeed}.`;
      const result = await Flow.generate.image({
        prompt: safePrompt(promptText, 3800),
        modelDisplayName: model,
        aspectRatio,
        referenceImageMediaIds: [refiningTarget.mediaId, ...productRefs.map(m => m.mediaId)].slice(0, 10)
      });
      setResults(prev => [result, ...prev]);
    } catch (err) { setError("Refine failed."); }
    finally { setIsGenerating(false); }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      {/* Sidebar */}
      <div className="w-[300px] h-full border-r border-[rgba(218,220,224,0.15)] flex flex-col px-[10px] py-[12px] bg-[#0e0e0e] z-20">
        <div className="flex-1 flex flex-col gap-[20px] overflow-y-auto dark-scrollbar pr-1">

          <div className="flex flex-col gap-2">
            <SectionLabel>1. References</SectionLabel>
            <MultiImageUpload items={productRefs} onUpdate={setProductRefs} max={4} placeholder="SKU" />
            <MultiImageUpload items={styleRefs} onUpdate={setStyleRefs} max={4} placeholder="Mood" />
          </div>

          <div className="flex flex-col gap-2">
            <SectionLabel>2. Configuration</SectionLabel>
            <div className="flex flex-col gap-1.5 px-1">
              <SegmentedToggle value={activeTab} onChange={(v) => setActiveTab(v as any)} items={[{ value: 'Campaign', label: '7-Shot' }, { value: 'Single', label: 'Single' }]} />
              <TextInput value={batchCustomDirective} onChange={setBatchCustomDirective} placeholder="Campaign theme..." className="h-[60px]" />
            </div>
          </div>

          <div className="flex flex-col gap-2">
            <SectionLabel>3. Engine Specs</SectionLabel>
            <div className="flex flex-col gap-1.5 px-1">
              <FieldDropdown label="Model" value={model} options={['🍌 Nano Banana Pro', '🍌 Nano Banana 2', 'Imagen 4']} onChange={setModel} />
              <div className="flex gap-1">
                <DragNumberField label="Seed" value={seed} onChange={setSeed} className="flex-1" />
                <div className="w-[80px]">
                  <IconToggleBar value={isSeedLocked} onChange={setIsSeedLocked} items={[{ value: true, icon: <span className="material-symbols-outlined text-[16px]">lock</span> }, { value: false, icon: <span className="material-symbols-outlined text-[16px]">lock_open</span> }]} />
                </div>
              </div>
              <FieldDropdown label="Aspect Ratio" value={aspectRatio} options={['1:1', '16:9', '9:16', '4:3', '3:4']} onChange={(v: any) => setAspectRatio(v)} />
            </div>
          </div>

          <div className="flex flex-col gap-2 mt-2">
            <SectionLabel>4. Presets</SectionLabel>
            <div className="flex flex-col gap-1.5 px-1">
              {presets.length > 0 && (
                <FieldDropdown 
                  label="Saved Presets" 
                  value="Select..." 
                  options={presets.map(p => p.name)} 
                  onChange={(val) => {
                    const found = presets.find(p => p.name === val);
                    if (found) loadPreset(found);
                  }} 
                />
              )}
              <PillButton variant="outline" onClick={saveToPresets} icon={<span className="material-symbols-outlined text-[16px]">save</span>}>Save Current</PillButton>
            </div>
          </div>
        </div>

        <div className="pt-4 mt-auto border-t border-white/5 flex flex-col gap-2">
          {appStatus === 'idle' && (
            <PillButton variant="solid" onClick={handleLaunchCampaign} disabled={productRefs.length === 0} icon={<span className="material-symbols-outlined text-[18px]">rocket_launch</span>}>
              Launch Project
            </PillButton>
          )}
          {(appStatus === 'analyzing' || appStatus === 'generating') && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center gap-2 px-3 py-2 bg-white/5 border border-white/10 rounded-xl">
                 <span className="material-symbols-outlined text-[16px] text-[#969696] animate-spin">refresh</span>
                 <span className="text-[10px] font-bold text-white uppercase tracking-wider">{appStatus === 'analyzing' ? 'Analyzing SKU...' : `Generating ${batchProgress.current + 1}/${batchProgress.total}`}</span>
              </div>
              <PillButton variant="outline" onClick={() => stopRequested.current = true} icon={<span className="material-symbols-outlined text-[18px] text-red-500">stop</span>}>Abort</PillButton>
            </div>
          )}
          {appStatus === 'reviewing' && (
             <PillButton variant="filled" onClick={confirmAndLaunch} icon={<span className="material-symbols-outlined text-[18px]">check_circle</span>}>Ready to Generate</PillButton>
          )}
          {error && <p className="text-[10px] text-red-400 font-medium px-2">{error}</p>}
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 h-full bg-[#0a0a0a] overflow-y-auto dark-scrollbar p-8">
        <div className="max-w-6xl mx-auto flex flex-col gap-6">

          {appStatus === 'reviewing' ? (
            <div className="flex flex-col gap-8 py-10 fade-in">
              <div className="flex flex-col gap-2">
                <h2 className="text-[18px] font-bold text-white tracking-tight flex items-center gap-2">
                   <span className="material-symbols-outlined text-amber-500">fact_check</span>
                   Review Analysis Before Launch
                </h2>
                <p className="text-white/40 text-[12px]">Confirm the model understands the product, identity, and garment architecture.</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="flex flex-col gap-3">
                  <SectionLabel>PRODUCT LOCK (SKU Fidelity)</SectionLabel>
                  <TextInput value={productLock} onChange={setProductLock} className="h-[240px] border-amber-500/20 bg-amber-500/5 text-amber-50/90" />
                </div>
                <div className="flex flex-col gap-3">
                  <SectionLabel>IDENTITY LOCK (Model Features)</SectionLabel>
                  <TextInput value={identityLock} onChange={setIdentityLock} className="h-[240px] border-blue-500/20 bg-blue-500/5 text-blue-50/90" />
                </div>
                <div className="flex flex-col gap-3">
                  <SectionLabel>GARMENT LOCK (Fixed Outfit)</SectionLabel>
                  <TextInput value={garmentLock} onChange={setGarmentLock} className="h-[240px] border-emerald-500/20 bg-emerald-500/5 text-emerald-50/90" />
                </div>
              </div>

              <div className="flex gap-3 justify-center mt-4">
                 <PillButton variant="outline" onClick={() => setAppStatus('idle')} className="w-auto px-10">Go Back</PillButton>
                 <PillButton variant="solid" onClick={confirmAndLaunch} className="w-auto px-10">Confirm & Launch 7 Shots</PillButton>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {appStatus === 'generating' && (
                <div className="aspect-[3/4] rounded-2xl animate-shimmer border border-white/10 flex flex-col items-center justify-center gap-4 bg-[#111]">
                   <span className="material-symbols-outlined text-white/20 text-[48px] pulse-ring">center_focus_strong</span>
                   <span className="text-white/30 text-[10px] uppercase font-bold tracking-[2px]">Capturing...</span>
                </div>
              )}
              {results.map((res, i) => (
                <div key={res.mediaId} className="relative group aspect-[3/4] rounded-2xl overflow-hidden border border-white/10 bg-[#111] fade-in">
                  <img src={`data:${res.mimeType};base64,${res.base64}`} alt="Output" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  {res.validation && (
                    <div className={`absolute top-3 left-3 flex items-center gap-1.5 px-2 py-1 rounded-lg backdrop-blur-md border ${res.validation.pass ? 'bg-green-500/10 border-green-500/20 text-green-400' : 'bg-red-500/10 border-red-500/20 text-red-400'}`}>
                      <span className="material-symbols-outlined text-[14px]">{res.validation.pass ? 'verified' : 'report'}</span>
                      <span className="text-[9px] font-black tracking-wider">{res.validation.pass ? 'PASS' : 'QC FAIL'}</span>
                    </div>
                  )}
                  <div className="absolute top-3 right-3 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => { setRefiningTarget(res); setIsEditModalOpen(true); }} className="w-8 h-8 rounded-lg bg-black/80 flex items-center justify-center border border-white/10 text-white hover:bg-white hover:text-black">
                      <span className="material-symbols-outlined text-[16px]">tune</span>
                    </button>
                    <button onClick={() => Flow.download({ base64: res.base64, mimeType: res.mimeType, filename: `shot_${i}.png` })} className="w-8 h-8 rounded-lg bg-black/80 flex items-center justify-center border border-white/10 text-white hover:bg-white hover:text-black">
                      <span className="material-symbols-outlined text-[16px]">download</span>
                    </button>
                  </div>
                </div>
              ))}
              {results.length === 0 && appStatus === 'idle' && (
                <div className="col-span-full h-[40vh] flex flex-col items-center justify-center text-center opacity-10 gap-4 select-none">
                  <span className="material-symbols-outlined text-[80px]">photo_camera</span>
                  <p className="text-[14px] uppercase tracking-[8px] text-white">Studio Ready</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <PromptModal isOpen={isEditModalOpen} onAccept={handleRefine} onCancel={() => setIsEditModalOpen(false)} />
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

// 5.1 SectionLabel
export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2 mb-1.5">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

// 5.2 PillButton
export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, disabled, className = '' }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
