// 5.10 PromptModal
export const PromptModal: React.FC<{
  isOpen: boolean; onAccept: (value: string) => void; onCancel: () => void;
}> = ({ isOpen, onAccept, onCancel }) => {
  const [value, setValue] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => { if (isOpen) { setValue(''); setTimeout(() => textareaRef.current?.focus(), 50); } }, [isOpen]);
  useEffect(() => {
    if (!isOpen) return;
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.preventDefault(); onCancel(); } };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [isOpen, onCancel]);

  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center" onClick={onCancel}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
      <div className="relative w-[300px] border border-[#595959] rounded-2xl overflow-hidden"
        style={{ background: '#1a1a1a' }} onClick={(e) => e.stopPropagation()}>
        <div className="px-4 pt-4 pb-2">
          <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
            Refine this image
          </span>
        </div>
        <div className="px-4 pb-3">
          <textarea ref={textareaRef} value={value} onChange={(e) => setValue(e.target.value)}
            placeholder="Describe your adjustments..."
            className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[80px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.5)] tracking-[0.1px] focus:outline-none transition-colors" />
        </div>
        <div className="flex gap-[5px] px-4 pb-4">
          <button type="button" onClick={onCancel}
            className="flex-1 h-[34px] rounded-xl border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-white tracking-[0.1px] transition-all cursor-pointer select-none">
            Cancel
          </button>
          <button type="button" onClick={() => onAccept(value)}
            className="flex-1 h-[34px] rounded-xl bg-white hover:bg-gray-200 active:bg-gray-300 text-[12px] font-medium text-black tracking-[0.1px] transition-all cursor-pointer select-none">
            Accept
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Flow, MediaItem } from 'flow-sdk';

interface Props {
  items: MediaItem[];
  onUpdate: (items: MediaItem[]) => void;
  max: number;
  placeholder: string;
}

export const MultiImageUpload: React.FC<Props> = ({ items, onUpdate, max, placeholder }) => {
  const handleAdd = async () => {
    try {
      const selected = await Flow.media.selectMultiple({ 
        filter: 'image', 
        maxCount: Math.max(1, max - items.length) 
      });
      onUpdate([...items, ...selected]);
    } catch (e) {}
  };

  const remove = (id: string) => onUpdate(items.filter(i => i.mediaId !== id));

  return (
    <div className="grid grid-cols-2 gap-1.5 px-2">
      {items.map(item => (
        <div key={item.mediaId} className="relative aspect-square rounded-xl overflow-hidden border border-[#595959] bg-[#1a1a1a] group">
          <img src={`data:${item.mimeType};base64,${item.base64}`} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
          <button 
            onClick={() => remove(item.mediaId)}
            className="absolute top-1 right-1 w-6 h-6 rounded-lg bg-black/80 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 hover:bg-white hover:text-black"
          >
            <span className="material-symbols-outlined text-[14px]">close</span>
          </button>
        </div>
      ))}
      {items.length < max && (
        <button 
          onClick={handleAdd}
          className="aspect-square rounded-xl border border-dashed border-[#595959] hover:border-[#7a7a7a] hover:bg-white/5 flex flex-col items-center justify-center gap-1 transition-all"
        >
          <span className="material-symbols-outlined text-[rgba(218,220,224,0.3)] text-[20px]">add_photo_alternate</span>
          <span className="text-[9px] text-[rgba(218,220,224,0.3)] uppercase font-bold tracking-wider">{placeholder}</span>
        </button>
      )}
    </div>
  );
};
